/**
 * Real encoder output, kept as base64 headers.
 *
 * Produced once by Sharp/libvips 8.15.3 at the dimensions in each name, then
 * truncated to the first 4KB - which is all a header parser reads. They are
 * genuine encoded bytes rather than hand-written signatures, because a parser
 * checked only against headers the test itself invented proves that the two
 * agree with each other and nothing else.
 *
 * `pngBomb_9000x9000` is the case that matters most: 257KB on disk, 81 million
 * pixels once decoded.
 */
export const REAL_IMAGE_HEADERS: Record<string, string> = {
  png_640x480: '',
  jpeg_1024x768: '',
  jpegProgressive_800x600: '',
  webpLossy_333x777: '',
  webpLossless_300x200: 'UklGRiQAAABXRUJQVlA4TBgAAAAvK8ExAAdQrXoUtP8BAEX6/58i+p/6/zU=',
  gif_120x90: 'R0lGODlheABaAIAAAExpcR5aoCH/C05FVFNDQVBFMi4wAwEAAAAh+QQFAAAAACwAAAAAeABaAAACeYyPqcvtD6OctNqLs968+w+G4kiW5omm6sq27gvH8kzX9o3n+s73/g8MCofEovGITCqXzKbzCY1Kp9Sq9YrNarfcrvcLDovH5LL5jE6r1+y2+w2Py+f0uv2Oz+v3/L7/DxgoOEhYaHiImKi4yNjo+AgZKTlJWWmZVAAAOw==',
  pngBomb_9000x9000: '',
  avif_13000x100: '',
  heic_13000x100: '',
  avif_100x100: ''
};

/**
 * Whole animated files, not headers.
 *
 * A GIF is the one format whose frame count cannot be read from its header: the
 * frames are simply appended, so the only way to count them is to walk the block
 * stream to the trailer. These fixtures are therefore complete files rather than
 * the first 4KB, and they are deliberately 4x4 — a frame flood is cheap in
 * pixels and expensive in per-frame work, which is exactly the case the frame
 * limit exists for and the case no pixel budget would ever catch.
 *
 * Regenerate with:
 *
 * ```
 * node file-server/scripts/generate-comment-image-fixtures.js
 * ```
 *
 * That script writes the GIFs itself — Sharp cannot author a multi-page GIF from
 * raw pixels — and then hands every one of them back to libvips, refusing to
 * emit a fixture the file server's own decoder does not read as intended. The
 * counts and delays below are libvips' reading, not the generator's intent.
 */
export const ANIMATED_IMAGE_FILES: Record<string, string> = {
  /** 300 frames of 40ms: exactly on the frame limit, 12s, 4800 pixels. */
  gif_4x4_300frames: '',
  /** 301 frames: one past the limit and nothing else about it is wrong. */
  gif_4x4_301frames: '',
  /** 100 frames of 500ms: 50 seconds, well past the 30s duration limit. */
  gif_4x4_50seconds: ''
};
